 atomic(P/'actual_cached_CPU_cost.json',dict(stage_clocks=exits,prediction_seal_wall_seconds=read(D/'sealed.json')['elapsed_wall_seconds'],nested_windows_not_additive=True,new_Source=0,new_expert=0,new_GPU=0,new_model=0,new_optimizer=0,inherited_Source_expert_acquisition_nonzero=True,deployment_latency=False))
 rec=dict(status='32same_actor_object_actionpairs64queries_allarrays_audited_ROOTinterpreted_PENDING_publication',scientific_fingerprint=validate()['fingerprint'],pairs=32,queries=64,independent_videos=32,audit_sha256=sha(D/'audit_receipt.json'),analysis_sha256=sha(P/'ANALYSIS.md'),report_sha256=sha(P/'report.json'),controller_actual_wait=outer,all3actualstages_exited0=True,new_Source=0,new_expert=0,new_GPU=0,new_model=0,new_optimizer=0,Current_or_paper_changed=False,time=time.time());atomic(D/'ROOT_completion.json',rec);atomic(P/'completion_scalars.json',rec);print(json.dumps({k:s[k]for k in ['JointPrior_t_percent','CorrectedROI_t_percent','visual_gain_t_pp','own_feature_gain_t_pp','own_evidence_gain_t_pp','CorrectedROI_assignment_margin_pp','CommonPrior_assignment_margin_pp','text_metadata_L_exact_percent']}))
